import{_ as t,o as r,c as i,a3 as a}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Independent design reviews","description":"","frontmatter":{},"headers":[],"relativePath":"reviews/index.md","filePath":"reviews/index.md","lastUpdated":1794376220000}'),n={name:"reviews/index.md"};function d(s,e,o,c,l,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="independent-design-reviews" tabindex="-1">Independent design reviews <a class="header-anchor" href="#independent-design-reviews" aria-label="Permalink to &quot;Independent design reviews&quot;">​</a></h1><p>These are original analyses applying published principles. Robert C. Martin, Erich Gamma, Richard Helm, Ralph Johnson, John Vlissides, and Graydon Hoare did not participate, review this repository, or endorse it. The reviews do not imitate their voices or invent their opinions.</p><h2 id="three-perspectives" tabindex="-1">Three perspectives <a class="header-anchor" href="#three-perspectives" aria-label="Permalink to &quot;Three perspectives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lens</th><th>Primary question</th><th>Read the review</th></tr></thead><tbody><tr><td>Robert C. Martin&#39;s architecture principles</td><td>Do source dependencies protect application policies from infrastructure?</td><td><a href="/knowledge-lab/reviews/clean-architecture">Clean Architecture review</a></td></tr><tr><td>Gang of Four design patterns</td><td>Which variation points and collaborations justify a pattern?</td><td><a href="/knowledge-lab/reviews/design-patterns">Design patterns review</a></td></tr><tr><td>Rust design and Graydon Hoare&#39;s early work</td><td>Are ownership, failure, resource bounds, and native boundaries explicit?</td><td><a href="/knowledge-lab/reviews/rust-design">Rust design review</a></td></tr></tbody></table><p>Rust began with Hoare&#39;s initial design and implementation and subsequently evolved through a large community. The Rust review separates historical primary material from modern Rust/Tokio behavior.</p><h2 id="findings-carried-into-the-architecture" tabindex="-1">Findings carried into the architecture <a class="header-anchor" href="#findings-carried-into-the-architecture" aria-label="Permalink to &quot;Findings carried into the architecture&quot;">​</a></h2><p>P1 means a design or implementation gate before depending on the affected behavior. P2 means a required refinement during the first vertical slice. These are priorities for a draft, not reports of deployed defects.</p><table tabindex="0"><thead><tr><th>Priority</th><th>Finding</th><th>Draft response</th><th>Remaining proof</th></tr></thead><tbody><tr><td>P1</td><td>Ambiguous run ownership permits stale completion</td><td>One owner, attempt fencing, ordered terminal transitions</td><td>Race and failure tests</td></tr><tr><td>P1</td><td>Generic search adapters can hide changed semantics</td><td>Capability and evidence contracts</td><td>Exact/ANN and filtered conformance tests</td></tr><tr><td>P1</td><td>Generated claims can lose evidence and uncertainty</td><td>Source spans, revision, qualifiers, derived-view separation</td><td>Grounding and correction evaluation</td></tr><tr><td>P1</td><td>Competing workflow schedulers create inconsistent retries</td><td>One progression owner; broker role explicit</td><td>Recovery prototype</td></tr><tr><td>P1</td><td>Blocking and unbounded work can stall chat</td><td>Bounded database/CPU workers, admission and buffer limits</td><td>Concurrent-load measurements</td></tr><tr><td>P1</td><td>Native extensions introduce an FFI trust boundary</td><td>Pin builds, validate compatibility, test recovery</td><td>Extension qualification</td></tr><tr><td>P2</td><td>Displayed text durability is unspecified</td><td>Explicit policy decision in stream contract</td><td>Crash/latency comparison</td></tr><tr><td>P2</td><td>Abstractions and services may outgrow actual variation</td><td>Focused ports; deployment split justified by measurements</td><td>First vertical slice review</td></tr></tbody></table><p>The main drafts include the recommended constraints. Their implementation remains future work. Read <a href="/knowledge-lab/architecture/contracts">contracts</a> for protocol obligations and <a href="/knowledge-lab/validation">validation</a> for the verification plan.</p>',9)])])}const m=t(n,[["render",d]]);export{u as __pageData,m as default};
